INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Box_Skip', 'Box Skip', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'You will need several boxes lined up about 8 feet apart. Begin facing the first box with one leg slightly behind the other. Drive off the back leg, attempting to gain as much height with the hips as possible. Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box. Then, step to the next box and repeat.'),
('Box_Squat', 'Box Squat', 'legs', ARRAY['legs','legs','legs','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders'),
('Box_Squat_with_Bands', 'Box Squat with Bands', 'legs', ARRAY['legs','legs','legs','legs','legs','back']::text[], 'barbell', 'powerlifting', 'expert', 'Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don''t move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. '),
('Box_Squat_with_Chains', 'Box Squat with Chains', 'legs', ARRAY['legs','legs','legs','legs','legs','back']::text[], 'barbell', 'strength', 'expert', 'Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement. Begin by stepping under the bar and placing it across the '),
('Brachialis-SMR', 'Brachialis-SMR', 'arms', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller. Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides.'),
('Bradford_Rocky_Presses', 'Bradford/Rocky Presses', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position. Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms. Now lower the bar down to the back of the head slowly as you inhale. Lift the bar back up to the starting'),
('Butt-Ups', 'Butt-Ups', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle. Arch your back slightly out rather than keeping your back completely straight. Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of the movement. Lower back down slowly to your starting posit'),
('Butt_Lift_Bridge', 'Butt Lift (Bridge)', 'legs', ARRAY['legs']::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position. Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second. Slowly go back to the starting position as you breathe in.'),
('Butterfly', 'Butterfly', 'chest', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Sit on the machine with your back flat on the pad. Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position. Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second. Return back to the starting position slowly as you inhale until your chest muscles are fully stretched. Repeat for the recommended am'),
('Cable_Chest_Press', 'Cable Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'cable', 'strength', 'beginner', 'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement. After pausing at full extension, return to th starting position, keeping tension on the cabl'),
('Cable_Crossover', 'Cable Crossover', 'chest', ARRAY['shoulders']::text[], 'cable', 'strength', 'beginner', 'To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand. Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position. With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side '),
('Cable_Crunch', 'Cable Crunch', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Kneel below a high pulley that contains a rope attachment. Grasp cable rope attachment and lower the rope until your hands are placed next to your face. Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position. With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second. Slowly return to th'),
('Cable_Deadlifts', 'Cable Deadlifts', 'legs', ARRAY['arms','legs','legs','back']::text[], 'cable', 'strength', 'beginner', 'Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights. To begin, squat down be flexing your hips and knees until you can reach the handles. After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement. After reaching a full standing position, Return to the starting position and repeat.'),
('Cable_Hammer_Curls_-_Rope_Attachment', 'Cable Hammer Curls - Rope Attachment', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it. Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary. Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position. Using your biceps, pull your arms up as you exhale until your biceps touch your for'),
('Cable_Hip_Adduction', 'Cable Hip Adduction', 'legs', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away. Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley. Now step out and away from the stack with a wide stance and grasp the bar of the pulley system. Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position. Now perform the movement by movin'),
('Cable_Incline_Pushdown', 'Cable Incline Pushdown', 'back', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position. Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the mov'),
('Cable_Incline_Triceps_Extension', 'Cable Incline Triceps Extension', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor. Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contra'),
('Cable_Internal_Rotation', 'Cable Internal Rotation', 'shoulders', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead. Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position. Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forea'),
('Cable_Iron_Cross', 'Cable Iron Cross', 'chest', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand. Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a "T". This will be your starting position. Keeping the elbows extended, pull your arms straight to your sides. Return your arms back to the starting position after a pause at the peak contraction. Continue the movement for the prescribed number of re'),
('Cable_Judo_Flip', 'Cable Judo Flip', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands. Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip. Shift your weight between your feet as you twist and crunch forward, pulling the cable downward. Return to the starting position and repeat until failure. Then, reposition and repeat the same series of moveme'),
('Cable_Lying_Triceps_Extension', 'Cable Lying Triceps Extension', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down. With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position. Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in a'),
('Cable_One_Arm_Tricep_Extension', 'Cable One Arm Tricep Extension', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack. Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This wi'),
('Cable_Preacher_Curl', 'Cable Preacher Curl', 'arms', ARRAY['arms']::text[], 'cable', 'strength', 'beginner', 'Place a preacher bench about 2 feet in front of a pulley machine. Attach a straight bar to the low pulley. Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley. Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position. Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this m'),
('Cable_Rear_Delt_Fly', 'Cable Rear Delt Fly', 'shoulders', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head. Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position. Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement. Pause at the end of the motion before returning the handles to the start position.'),
('Cable_Reverse_Crunch', 'Cable Reverse Crunch', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it. Sit down with your feet toward the pulley and attach the cable to your ankles. Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are. With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor. Pause for a moment and in a slow and contr'),
('Cable_Rope_Overhead_Triceps_Extension', 'Cable Rope Overhead Triceps Extension', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope to the bottom pulley of the pulley machine. Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position. Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when y'),
('Cable_Rope_Rear-Delt_Rows', 'Cable Rope Rear-Delt Rows', 'shoulders', ARRAY['arms','back']::text[], 'cable', 'strength', 'beginner', 'Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back. Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out. Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position. Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out '),
('Cable_Russian_Twists', 'Cable Russian Twists', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle attachment, and position the cable to a middle pulley position. Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are. Keep your hips elevated and abs'),
('Cable_Seated_Crunch', 'Cable Seated Crunch', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Seat on a flat bench with your back facing a high pulley. Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position. With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step. As you inhale, go back to the initial position slowly. Repeat for the recommend'),
('Cable_Seated_Lateral_Raise', 'Cable Seated Lateral Raise', 'shoulders', ARRAY['back','back']::text[], 'cable', 'strength', 'beginner', 'Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley. Now sit at the edge of the flat bench behind you with your feet placed in front of your knees. Bend forward while keeping your back flat and rest your torso on the thighs. Have someone give you the single handles attached to the pulleys. Grasp the le'),
('Cable_Shoulder_Press', 'Cable Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'cable', 'strength', 'beginner', 'Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position. Keeping your head and chest up, extend through the elbow to press the handles directly over head. After pausing at the top, return to the starting position and repeat.'),
('Cable_Shrugs', 'Cable Shrugs', 'back', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip. Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position. Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shou'),
('Cable_Wrist_Curl', 'Cable Wrist Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment. Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees. Start out by curling your wrist upwards and exhaling. Keep the contraction for a second. Slowly lower your wrists back down to the starting position while inhaling. Yo'),
('Calf-Machine_Shoulder_Shrug', 'Calf-Machine Shoulder Shrug', 'back', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position. Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second. Slowly return to the starting position as you inhale. Repeat for the recommended amount of repetitions.'),
('Calf_Press', 'Calf Press', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform. Select an appropriate weight, and grasp the handles. This will be your starting position. Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible. After a brief pause, reverse the mot'),
('Calf_Press_On_The_Leg_Press_Machine', 'Calf Press On The Leg Press Machine', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of perfo'),
('Calf_Raise_On_A_Dumbbell', 'Calf Raise On A Dumbbell', 'legs', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise. Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position. Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement.'),
('Calf_Raises_-_With_Bands', 'Calf Raises - With Bands', 'legs', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides. While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position. Keeping the hands by your shoulder, stand up on your t'),
('Calf_Stretch_Elbows_Against_Wall', 'Calf Stretch Elbows Against Wall', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Stand facing a wall from a couple feet away. Lean against the wall, placing your weight on your forearms. Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively.'),
('Calf_Stretch_Hands_Against_Wall', 'Calf Stretch Hands Against Wall', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Stand facing a wall from several feet away. Stagger your stance, placing one foot forward. Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line. Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides.'),
('Calves-SMR', 'Calves-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position. Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg.'),
('Car_Deadlift', 'Car Deadlift', 'legs', ARRAY['arms','legs','legs','back','back']::text[], 'other', 'strongman', 'intermediate', 'This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs. Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With your feet and your grip set, take a big breath and then lower'),
('Car_Drivers', 'Car Drivers', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position. Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side. Reverse the motion, turning it all the way to the opposite side. Repeat for the recommended amount of repetit'),
('Carioca_Quick_Step', 'Carioca Quick Step', 'legs', ARRAY['core','legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position. With your right foot, quick step behind and pull the knee up. Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side.'),
('Cat_Stretch', 'Cat Stretch', 'back', ARRAY['back','back']::text[], 'other', 'stretching', 'beginner', 'Position yourself on the floor on your hands and knees. Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop. Hold for 15 seconds.'),
('Catch_and_Overhead_Throw', 'Catch and Overhead Throw', 'back', ARRAY['core','chest','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'Begin standing while facing a wall or a partner. Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward. Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner.'),
('Chain_Handle_Extension', 'Chain Handle Extension', 'arms', ARRAY[]::text[], 'other', 'powerlifting', 'intermediate', 'You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up. Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated. Pause at the lockout, and reverse the motion to return to the starting position.'),
('Chain_Press', 'Chain Press', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'powerlifting', 'intermediate', 'Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position. Lower the chains by flexing the elbows, unloading some of the chain onto the floor. Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout.'),
('Chair_Leg_Extended_Stretch', 'Chair Leg Extended Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Sit upright in a chair and grip the seat on the sides. Raise one leg, extending the knee, flexing the ankle as you do so. Slowly move that leg outward as far as you can, and then back to the center and down. Repeat for your other leg.'),
('Chair_Lower_Back_Stretch', 'Chair Lower Back Stretch', 'back', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Sit upright on a chair. Bend to one side with your arm over your head. You can hold onto the chair with your free hand. Hold for 10 seconds, and repeat for your other side.')
